import numpy as np


def zscores(values):
    mean = sum(values) / len(values)
    var = sum((x - mean) ** 2 for x in values) / len(values)
    std = var ** 0.5
    out = []
    for x in values:
        out.append((x - mean) / std)
    return np.array(out)

